'use strict';
const $=s=>document.querySelector(s),E=Economy,KEY='new-formosa-life-v4';const money=n=>Number(n).toLocaleString('zh-TW',{maximumFractionDigits:2}),fmt=money;
let state;try{const saved=JSON.parse(localStorage.getItem(KEY)||localStorage.getItem('new-formosa-life-v3')||'null');const old=JSON.parse(localStorage.getItem('new-formosa-v1')||'{}');state=saved&&[3,4].includes(saved.version)?saved:E.initial(old||{});}catch{state=E.initial();}
E.upgrade(state);
let page='home',tavernGame='bingo',bingoMode='basic',bingoNumbers=[],lottoNumbers=[],bingoStake=25,selectedCity=state.city||'臺北市',cityRegion='all',toastTimer,order=null,spinning=false;
const NAV=[['home','⌂','我的生活'],['jobs','▣','就業所'],['tavern','♧','巷口酒館'],['shop','▤','生活商店'],['auction','⚑','拍賣行'],['stocks','↗','寶島股市']];
function icon(k){const label={cash:'NT$',xp:'EXP',tax:'稅',gold:'G',energy:'ϟ'};return `<span class="resource-icon ${k}" aria-hidden="true">${label[k]}</span>`;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('無法儲存進度，請確認裝置儲存空間');}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function modal(html){$('#modal').classList.remove('map-dialog');$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function clock(ms){let n=Math.max(0,Math.ceil(ms/1000));const h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=n%60;return (h?h.toString().padStart(2,'0')+':':'')+m.toString().padStart(2,'0')+':'+s.toString().padStart(2,'0');}
function stamp(t){return new Date(t).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});}
function title(k,t,right=''){return `<div class="page-title"><div><div class="eyebrow">${k}</div><h1>${t}</h1></div>${right}</div>`;}
function header(){E.energy(state,Date.now());$('#resources').innerHTML=`<button class="resource" data-action="wallet" aria-label="新台幣 ${money(state.cash)}">${icon('cash')} ${money(state.cash)}</button><button class="resource premium" data-action="gold" aria-label="黃金 ${state.premium}">${icon('gold')} ${state.premium}</button><button class="resource" data-action="stamina" aria-label="電量 ${state.energy} / 100">${icon('energy')} ${state.energy}/100 <b>＋</b></button>`;$('#level').textContent=1+Math.floor(state.exp/500);const banner=$('#broadcast');if(banner){banner.hidden=!state.broadcasts.length;banner.textContent=state.broadcasts.length?'📣 全島廣播（本機預演） '+state.broadcasts[0].text:'';}}
function cityLevel(){return E.city(state).level;}
function currentJob(){return state.jobs.map(j=>`<div class="active-job"><img src="assets/${E.JOBS[j.job][2]}.png" alt="工作職人"><div><span class="badge">${j.stars} 星 · 進行中</span><h3>${E.JOBS[j.job][0]}</h3><p>稅前 ${j.rate} · 勞健保稅 10% · 實領 ${money(j.rate*.9)}</p><b data-until="${j.end}">${clock(j.end-Date.now())}</b><small> 離線也會完成</small></div></div>`).join('')+(state.jobResults.length?`<section class="panel"><h3>最近完成的工作</h3>${state.jobResults.slice(0,3).map(j=>`<p>${E.JOBS[j.job][0]} · 實領 NT$ ${money(j.pay)} · 小物 ${j.drops.length} 件</p>`).join('')}<button class="text-btn" data-action="next-jobs">收起完成紀錄</button></section>`:'');}
function home(){return `${title('A LITTLE LIFE IN FORMOSA','寶島生活日常',`<span class="badge">${state.city||'尚未選擇家鄉'}</span>`)}<section class="hero life-hero"><img src="assets/world.png" alt="Q版台灣海島小鎮"><div class="hero-copy"><span class="badge">${state.city?'我的家鄉 · '+state.city:'22 縣市，選一個家'}</span><h2>在寶島，好好過日子。</h2><p>找份工作、逛逛小店，偶爾到巷口坐坐。</p><button class="btn gold" data-page="jobs">${state.jobs.length?'查看目前工作':'找一份好工作'} ›</button> <button class="btn map-open" data-action="choose">探索台灣地圖</button></div></section><div class="life-summary"><div>${icon('cash')}<span>生活存款<b>${money(state.cash)}</b></span></div><div>${icon('energy')}<span>今日電量<b>${state.energy}<small> / 100</small></b></span></div><div>${icon('xp')}<span>社會歷練<b>${money(state.exp)}</b></span></div><div>${icon('tax')}<span>累積納稅金額<b>${money(state.tax)}</b></span></div></div>${currentJob()}<div class="district-grid"><button class="district work" data-page="jobs"><span class="district-icon">▣</span><span class="eyebrow">WORK & EARN</span><h3>就業所</h3><p>多份工作一起接，為城市累積稅收。</p><b>查看工作 ›</b></button><button class="district pub" data-page="tavern"><span class="district-icon">♧</span><span class="eyebrow">AFTER HOURS</span><h3>巷口酒館</h3><p>賓狗、大樂透，還有餃子老虎雞。</p><b>進去坐坐 ›</b></button><button class="district market" data-page="stocks"><span class="district-icon">↗</span><span class="eyebrow">FORMOSA EXCHANGE</span><h3>寶島股市</h3><p>城市升級解鎖標的，每小時新行情。</p><b>查看行情 ›</b></button></div><div class="life-bottom"><section class="panel"><div class="section-heading"><h3>我的隨身小物</h3><button class="text-btn" data-page="shop">前往商店 ›</button></div><p class="muted">工作完成後可能取得小物，可在商店出售。</p><div class="mini-inventory">${E.ITEMS.filter(i=>state.inventory[i.id]).map(i=>`<span>${i.icon} ${i.name} ×${state.inventory[i.id]}</span>`).join('')||'<span>背包還空著，先去接份工作吧。</span>'}</div></section><section class="panel"><h3>最近的生活紀錄</h3>${ledger(4)}</section></div><div class="notice">本機生活模擬 · 新台幣為不可兌現遊戲資源 · 城市人數與市場非真實資料</div>`;}
function ledger(n){return `<div class="ledger">${state.ledger.slice(0,n).map(x=>`<div><span>${x.text}<small>${stamp(x.at)}</small></span><b class="${x.delta>=0?'positive':'negative'}">${x.delta>0?'+':''}${x.delta?money(x.delta):'—'}</b></div>`).join('')||'<p class="muted">還沒有紀錄，新的生活正要開始。</p>'}</div>`;}
function jobs(){const c=E.city(state),cost=state.daily.refresh*50;return `${title('EMPLOYMENT OFFICE','城市就業所',`<span class="badge">Lv.${c.level} · 電量 ${state.energy}/100</span>`)}<div class="panel city-growth"><div class="section-heading"><h3>${state.city||'先加入一座城市'} · 最多 ${c.jobs} 份職缺</h3><button class="btn gold" data-action="refresh-jobs" ${state.premium<cost?'disabled':''}>${cost?'刷新 · '+cost+' 黃金':'每日免費刷新'}</button></div><p>每份工作 60 分鐘，可同時接多份；接下即從職缺移除，完成不自動補發。每日台灣時間 00:00 重置免費刷新，後續 50／100／150…黃金。</p><p>城市薪資加成 +${c.bonus}% · 勞健保稅 10% · 1～5 星固定掉落 1～5 件小物。</p></div>${currentJob()}<div class="jobs-grid">${state.offers.map(o=>{const j=E.JOBS[o.job];return `<article class="job-card"><div class="job-portrait"><img src="assets/${j[2]}.png" alt="${j[0]}職人"><span class="job-stars">${'★'.repeat(o.stars)}${'☆'.repeat(5-o.stars)}</span></div><div class="job-card-body"><span class="eyebrow">${o.stars} 星工作 · 60 分鐘</span><h2>${j[0]}</h2><p>${j[1]}</p><div class="job-rate"><span>${icon('cash')}<b>${o.rate}</b><small>/ 小時</small></span><span>${icon('energy')}<b>${o.energy}</b><small>/ 份</small></span></div><p class="muted">勞健保稅 ${money(o.rate*.1)} · 實領 ${money(o.rate*.9)}<br>完成獲得 ${o.stars} 件小物</p><button class="btn gold full" data-accept="${o.uid}" ${state.energy<o.energy||!state.city?'disabled':''}>開始工作 ›</button></div></article>`;}).join('')}</div>${state.offers.length?'':'<div class="panel"><h3>本批職缺已接完</h3><p>進行中的工作不受刷新影響，可使用上方按鈕取得新職缺。</p></div>'}<p class="muted">電量每 5 分鐘恢復 1，上限 100。工作按接取時薪資鎖定；城市升級後刷新可取得新加成與更多職缺。</p>`;}
function tavern(){return `${title('THE CORNER TAVERN','巷口酒館',`<span class="badge">純遊戲娛樂 · 無現金獎品</span>`)}<div class="tavern-heading"><div><span class="eyebrow">今晚，想玩哪一桌？</span><h2>工作結束，來坐一下。</h2><p>只使用遊戲賺取的新台幣；黃金無法兌換遊戲籌碼或彩金。</p></div><span class="tavern-sign">酒<br>館</span></div><div class="game-tabs">${[['bingo','BINGO','賓狗賓狗','每 5 分鐘'],['lotto','LOTTO','寶島大樂透','每 12 小時'],['slots','LUCKY LINE','餃子老虎雞','三格連線']].map(([id,en,n,time])=>`<button data-game="${id}" class="${tavernGame===id?'selected':''}"><small>${en}</small><b>${n}</b><span>${time}</span></button>`).join('')}</div>${tavernGame==='slots'?slotView():lotteryView(tavernGame)}`;}
function lotteryView(type){const isB=type==='bingo',r=E.period(state,type),last=E.draw(type,r.id-1,state.seed),selected=isB?bingoNumbers:lottoNumbers,max=isB?80:49,showNumbers=!isB||['basic','super'].includes(bingoMode);return `${!isB?`<div class="panel"><span class="badge">保底 10,000,000</span><h2>本期預估獎池 NT$ ${money(state.pools.lotto+state.tickets.filter(t=>t.type==='lotto'&&t.status==='pending'&&t.round===r.id).length*45)}</h2><p class="muted">已累積獎池加本期待結算投注；頭獎分配以開獎結算為準。</p></div>`:''}<section class="draw-clock"><div><span class="badge">第 ${r.id} 期</span><h3>${isB?'下一期賓狗開獎':'下一期大樂透開獎'}</h3><p>${stamp(r.end)}（台灣時間）</p></div><b data-until="${r.end}">${clock(r.end-Date.now())}</b></section><div class="lottery-layout"><section class="panel number-panel">${isB?`<div class="bingo-modes">${[['basic','基本選號'],['super','超級獎號'],['small','猜小'],['big','猜大'],['odd','猜單'],['even','猜雙']].map(([id,n])=>`<button data-mode="${id}" class="${bingoMode===id?'active':''}">${n}</button>`).join('')}</div>`:''}<div class="section-heading"><h3>${isB?bingoMode==='basic'?'選 1～10 個號碼':bingoMode==='super'?'預測第 20 個獎號':'預測 20 個開出號碼的分布':'從 01～49 選 6 個號碼'}</h3>${showNumbers?`<button class="text-btn" data-action="quick-pick">電腦選號 ↻</button>`:''}</div>${showNumbers?`<div class="number-grid">${Array.from({length:max},(_,i)=>i+1).map(n=>`<button data-number="${n}" aria-pressed="${selected.includes(n)}" class="${selected.includes(n)?'picked':''}">${String(n).padStart(2,'0')}</button>`).join('')}</div>`:`<div class="prediction"><b>${({small:'01～40 至少 13 個',big:'41～80 至少 13 個',odd:'單數至少 13 個',even:'雙數至少 13 個'})[bingoMode]}</b><p>符合條件即得投入金額的 6 倍。未達 13 個則不獲獎。</p></div>`}</section><aside class="ticket-slip"><span class="eyebrow">MY PLAY SLIP</span><h3>${isB?'賓狗選號單':'大樂透選號單'}</h3><div class="selected-balls">${showNumbers?(selected.length?selected.map(n=>`<b>${String(n).padStart(2,'0')}</b>`).join(''):'<span>從左側選擇號碼</span>'):`<b class="word-ball">${({small:'猜小',big:'猜大',odd:'猜單',even:'猜雙'})[bingoMode]}</b>`}</div><div class="slip-row"><span>選號數量／自動星等</span><b>${showNumbers?selected.length+(isB&&bingoMode==='basic'?' 星':' 個'):'分布預測'}</b></div><label class="field-label">${isB?'投入遊戲新台幣':'每注遊戲新台幣'}${isB?`<select id="bingo-stake">${[25,50,100].map(n=>`<option value="${n}" ${n===bingoStake?'selected':''}>${n}</option>`).join('')}</select>`:'<b class="fixed-price">50</b>'}</label><button class="btn gold full" data-action="place-ticket" ${(!isB&&selected.length!==6)||(isB&&showNumbers&&!selected.length)||state.cash<(isB?bingoStake:50)?'disabled':''}>確認參加 · NT$ ${isB?bingoStake:50}</button><p class="muted">每次投入內含 10% 娛樂稅，自動貢獻城市；賓狗按投入總額計算倍率，獎金不重複扣稅。離線開獎在下次開啟時結算。</p></aside></div><section class="panel draw-results"><div class="section-heading"><h3>${r.id===1?'尚無上一期開獎':'上一期開獎'}</h3><span class="muted">第 ${Math.max(1,r.id-1)} 期 · 本機模擬</span></div><div class="result-balls" ${r.id===1?'hidden':''}>${last.numbers.map(n=>`<span>${String(n).padStart(2,'0')}</span>`).join('')}<b>${isB?'超級獎號':'特別號'}</b><span class="special">${String(isB?last.super:last.special).padStart(2,'0')}</span></div></section><div class="lottery-bottom"><section class="panel"><h3>我的參加紀錄</h3>${ticketHistory(type)}</section><section class="panel rules-panel"><h3>遊戲規則與獎勵</h3>${isB?bingoRules():lottoRules()}</section></div>`;}
function bingoRules(){return `<p>每 5 分鐘從 01～80 開出 20 個不重複號碼，第 20 個為超級獎號。基本玩法可選 1～10 號，選號數即星數。</p><p>超級獎號猜中得 48 倍；猜大小／單雙需對應號碼至少 13 個，得 6 倍。所有倍數均為含本金的總彩金。</p><details><summary>基本玩法完整倍率表</summary><table class="rules-table"><thead><tr><th>選幾號</th><th>命中數：總彩金倍數</th></tr></thead><tbody>${Object.entries(E.BINGO_PAY).map(([n,p])=>`<tr><td>${n} 星</td><td>${Object.entries(p).map(([hits,m])=>`${hits} 中：${m} 倍`).join(' / ')}</td></tr>`).join('')}</tbody></table></details><p class="muted">未列組合不獲獎。倍率依提供的台彩參考表；每注 25 元起，未套用限期加碼。各玩法單期上限：1～9 星 1,000 萬、10 星 1 億、超級／大小／單雙 2,000 萬；超限按比例分配。</p>`;}
function lottoRules(){return `<h3>累積獎池 NT$ ${money(state.pools.lotto)}</h3><p>保底 10,000,000；每注 50 內含娛樂稅 5，45 在該期結算加入獎池。從本版啟用起每 12 小時一期。</p><p>先派固定獎，再按剩餘金額分配：貳獎 6.5%、參獎 7%、肆獎 4.5%，各獎等中獎注數均分；頭獎均分其他獎派發後的全部餘額。未發金額累積至下期，低於保底由系統補足。</p><table class="rules-table"><tr><th>獎項</th><th>命中</th><th>獎金</th></tr>${[['頭獎','6 主號','剩餘獎池全拿／均分'],['貳獎','5＋特別','6.5% 均分'],['參獎','5 主號','7% 均分'],['肆獎','4＋特別','4.5% 均分'],['伍獎','4 主號','2,000'],['陸獎','3＋特別','1,000'],['柒獎','2＋特別','400'],['普獎','3 主號','400']].map(a=>`<tr>${a.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</table><p class="muted">每注取最高獎；固定獎若超過獎池，按比例縮減。頭獎全拿與保底為本遊戲改版，非官方完整制度。獎池、廣播目前為本機模擬。</p>`;}
function ticketHistory(type){const tickets=state.tickets.filter(t=>t.type===type).slice(-8).reverse();return `<div class="ticket-history">${tickets.map(t=>`<article><div><b>第 ${t.round} 期</b><span class="badge">${t.status==='pending'?'等待開獎':t.award.tier}</span></div><p>${t.numbers.length?t.numbers.map(n=>String(n).padStart(2,'0')).join(' · '):({small:'猜小',big:'猜大',odd:'猜單',even:'猜雙'})[t.mode]}</p><small>投入 ${money(t.stake)}${t.status==='settled'?' · 彩金 '+money(t.award.prize)+'（已結算）':' · '+stamp(t.end)}</small></article>`).join('')||'<p class="muted">這一桌還沒有參加紀錄。</p>'}</div>`;}
function slotView(){const s=state.lastSlots;return `<section class="slot-machine"><span class="badge">PROGRESSIVE JACKPOT · 保底 100,000</span><h2>餃子・老虎・雞</h2><div class="jackpot-value">NT$ ${money(state.pools.slots)}</div><div class="slot-reels ${spinning?'spinning':''}">${(s?.reels||['🥟','🐯','🐔']).map(x=>`<span>${x}</span>`).join('')}</div><div class="slot-status" aria-live="polite">${spinning?'轉動中…':s?`${s.count} 次完成 · 大獎 ${s.wins} 次 · 合計 ${money(s.total)}`:'由左至右出現「餃子 → 老虎 → 雞」，獎池全拿！'}</div><div class="batch-actions">${[1,10,50].map(n=>`<button class="btn gold" data-spin="${n}" ${spinning||state.cash<n*50?'disabled':''}>轉 ${n} 次 · ${money(n*50)}</button>`).join('')}</div></section><section class="panel"><h3>獎池規則</h3><p>每次 50 元內含 5 元娛樂稅。未中獎的 45 元加入獎池；中獎領走目前全部獎池，系統重新補至 100,000。</p><p>每軸目標圖案機率各 1/32；指定順序三連中獎率 1/32,768。其他圖案不給獎，無倍率獎金。連轉逐次結算，需先備妥全額，可能多次中獎。</p><h3>全島大獎廣播 <small>本機預演</small></h3>${state.broadcasts.map(b=>`<p>📣 ${b.text} <small>${stamp(b.at)}</small></p>`).join('')||'<p class="muted">尚未有人中獎，等待下一位幸運島民。</p>'}<p class="muted">真人共用獎池與全遊戲廣播待多人伺服器串接。</p></section>`;}
function shop(){return `${title('THE NEIGHBORHOOD STORE','寶島生活商店')}<div class="shop-banner"><span class="badge">日常用品 · 小物回收 · 一番賞</span><h2>補點元氣，再繼續出發。</h2><p>買份便當存進背包，也把工作的小收穫換成生活費。</p></div><div class="section-heading shop-section"><h2>元氣補給</h2><button class="text-btn" data-action="stamina">查看電量 ›</button></div><div class="goods-grid">${E.GOODS.map(g=>`<article class="panel goods-card"><span class="goods-icon">${g.icon}</span><h3>${g.name}</h3><p>${g.desc}</p><span class="badge">電量 +${g.energy}</span><div class="goods-actions"><button class="btn gold" data-buy="${g.id}" ${state[g.currency]<g.price||(state.daily.goods[g.id]||0)>=g.limit?'disabled':''}>購買 · ${g.currency==='premium'?'黃金':'NT$'} ${g.price}（${state.daily.goods[g.id]||0}/${g.limit}）</button><button class="btn light" data-use="${g.id}" ${!state.food[g.id]||state.energy+g.energy>100?'disabled':''}>使用（${state.food[g.id]||0}）</button></div></article>`).join('')}</div><section class="panel shop-section"><div class="section-heading"><h2>工作小物回收</h2><span class="muted">每次出售 1 件</span></div><div class="sell-grid">${E.ITEMS.map(i=>`<div class="sell-row"><span class="item-symbol">${i.icon}</span><div><b>${i.name}</b><small>持有 ${state.inventory[i.id]||0} 件 · 機率 ${(i.weight/E.ITEMS.reduce((a,x)=>a+x.weight,0)*100).toFixed(2)}%</small></div><button class="btn light" data-sell="${i.id}" ${!state.inventory[i.id]?'disabled':''}>售出 +${i.sell}</button></div>`).join('')}</div></section><section class="ichiban shop-section"><div><span class="eyebrow">FORMOSA SOUVENIRS</span><h2>寶島生活一番賞</h2><p>每次 150 遊戲新台幣，隨機獲得一件紀念小物。</p><button class="btn gold" data-action="ichiban" ${state.cash<150?'disabled':''}>抽一次 · NT$ 150</button><p class="muted">每抽獨立，無限獎池；不同於實體有限籤的一番賞。<br>平均回收價值 140 新台幣（93.3%）；最低回收 90。無現金獎品。</p></div><div class="prize-grid">${E.PRIZES.filter(p=>!p.gold).map(p=>`<div><span>${p.icon}</span><b>${p.name}</b><small>${p.weight}% · 持有 ${state.collectibles[p.id]||0}</small><button class="text-btn" data-sell-prize="${p.id}" ${!state.collectibles[p.id]?'disabled':''}>出售 1 件 +${p.sell}</button></div>`).join('')}</div></section>${goldPrizes()}`;}
function goldPrizes(){return `<section class="ichiban shop-section"><div><span class="eyebrow">PREMIUM COLLECTION</span><h2>黃金典藏一番賞</h2><p>每抽 50 黃金 · 每抽必得元氣飲一瓶（回復 70 電量），再獲得一件收藏。</p><button class="btn gold" data-action="gold-prize" ${state.premium<50?'disabled':''}>抽一次 · 50 黃金</button><p class="muted">收藏參考價值平均 60 黃金，加上元氣飲參考價 30；這是收藏價值，不代表可回售、兌現或獲利。重複收藏仍保留件數。黃金儲值尚未接通。</p></div><div class="prize-grid">${E.PRIZES.filter(p=>p.gold).map(p=>`<div><span>${p.icon}</span><b>${p.name}</b><small>${p.weight}% · 參考 ${p.value} 黃金<br>持有 ${state.collectibles[p.id]||0} 件 · 不可回售</small></div>`).join('')}</div></section>`;}
function auction(){return `${title('FORMOSA AUCTION','寶島拍賣行',`<span class="badge">待設計</span>`)}<section class="auction-empty"><span>⚑</span><h2>好物，值得等一場好競標。</h2><p>未來將讓玩家上架物品、參與競標與收藏寶島好物。</p><div class="auction-roadmap"><b>物品上架</b><i>›</i><b>玩家競標</b><i>›</i><b>到期結標</b></div><p class="muted">競標規則、手續費、託管與交易保障尚待設計。<br>目前沒有上架或出價功能，也不會扣除資源。</p></section>`;}
function holdingsTotal(){return E.STOCKS.reduce((sum,s)=>sum+(state.holdings[s.id]?.qty||0)*state.market.prices[s.id]/100,0);}
function stocks(){const end=(state.market.hour+1)*E.HOUR;return `${title('FORMOSA STOCK EXCHANGE','寶島模擬股市',`<span class="badge">每小時更新</span>`)}<div class="market-summary"><div><small>可用遊戲新台幣</small><b>${money(state.cash)}</b></div><div><small>持股市值</small><b>${money(holdingsTotal())}</b></div><div><small>下一次行情更新</small><b data-until="${end}">${clock(end-Date.now())}</b></div></div><div class="market-notice">虛構公司與代號 · 本機規則模擬行情 · 每小時各股隨機 ±10% 內調整 · 與真實台股無關</div><div class="stock-table"><div class="stock-head"><span>股票 / 產業</span><span>成交價 / 漲跌</span><span>近 24 次走勢</span><span>持股 / 損益</span><span>交易</span></div>${E.STOCKS.filter((s,i)=>i<E.city(state).stocks||state.holdings[s.id]?.qty||state.shorts[s.id]?.qty).map(s=>{const p=state.market.prices[s.id],hist=state.market.history[s.id],prev=hist.at(-2)||p,change=(p-prev)/prev*100,h=state.holdings[s.id]||{qty:0,costCents:0},profit=(h.qty*p-h.costCents)/100;return `<article class="stock-row"><div><b>${s.name}</b><small>${s.id} · ${s.sector}<br>發行 100,000 · 可售 ${money(100000-(state.holdings[s.id]?.qty||0))} 股</small></div><div class="${change>=0?'stock-up':'stock-down'}"><b>${(p/100).toFixed(2)}</b><small>${change>=0?'▲':'▼'} ${Math.abs(change).toFixed(2)}%</small></div><canvas class="sparkline" data-stock-chart="${s.id}" width="170" height="55" aria-label="${s.name}歷史行情圖"></canvas><div><b>多 ${money(h.qty)} 股／空 ${money(state.shorts[s.id]?.qty||0)} 股</b>${state.shorts[s.id]?.qty?`<small>空單損益 ${money(state.shorts[s.id].proceeds-state.shorts[s.id].qty*p/100)}<br>維持率 ${((state.shorts[s.id].proceeds+state.shorts[s.id].margin)/(state.shorts[s.id].qty*p/100)*100).toFixed(1)}%</small>`:''}<small class="${profit>=0?'stock-up':'stock-down'}">${profit>=0?'+':''}${money(profit)}</small></div><div class="trade-buttons"><button data-trade="${s.id}" data-side="buy">買進</button><button data-trade="${s.id}" data-side="sell" ${!h.qty?'disabled':''}>賣出</button><button data-trade="${s.id}" data-side="short">放空</button><button data-trade="${s.id}" data-side="cover" ${!state.shorts[s.id]?.qty?'disabled':''}>回補</button></div></article>`;}).join('')}</div><div class="lottery-bottom"><section class="panel"><h3>交易說明</h3><p class="muted">紅漲綠跌，每 1 股為最小交易單位，1 張 = 1,000 股。以確認時的最新模擬成交價交易，買賣及放空回補均收 10% 遊戲交易稅。放空鎖定 90% 保證金與賣出價款，不能拿賣出款循環交易；每檔最多借券 10,000 股。維持率低於 130% 自動回補（本遊戲簡化規則，實際台股有追繳程序）。行情跨整點更新時須重新確認報價。價格下限 1、上限 100,000。城市目前解鎖 ${E.city(state).stocks}/${E.STOCKS.length} 檔。發行與借券額度為本機帳本，多人共用待串接。</p></section><section class="panel"><h3>最近帳目</h3>${ledger(5)}</section></div>`;}
function charts(){document.querySelectorAll('[data-stock-chart]').forEach(c=>{const ctx=c.getContext('2d'),arr=state.market.history[c.dataset.stockChart];if(!ctx)return;const values=arr.length>1?arr:[arr[0],arr[0]],min=Math.min(...values),max=Math.max(...values),range=max-min||1;ctx.clearRect(0,0,170,55);ctx.strokeStyle=values.at(-1)>=values[0]?'#cd6456':'#349177';ctx.lineWidth=2;ctx.beginPath();values.forEach((v,i)=>{const x=5+i/(values.length-1)*160,y=45-(v-min)/range*35;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);});ctx.stroke();});}
function render(){header();$('#nav').innerHTML=NAV.map(([id,i,n])=>`<button data-page="${id}" class="${page===id?'active':''}"><span>${i}</span>${n}${id==='auction'?'<em>籌備中</em>':''}</button>`).join('');$('#main').innerHTML=({home,jobs,tavern,shop,auction,stocks})[page]();if(page==='stocks')charts();}
function staminaModal(){modal(`<div class="eyebrow">TAKE A BREAK</div><h2>${icon('energy')} 電量補給站</h2><div class="stamina-number">${state.energy}<span> / 100</span></div><div class="progress"><i style="width:${state.energy}%"></i></div><p>每 5 分鐘恢復 1 點，離線也會恢復。工作開始時一次扣除整段所需電量。</p><div class="food-bag">${E.GOODS.map(g=>`<div><span>${g.icon} ${g.name} · +${g.energy}</span><button class="btn light" data-use="${g.id}" ${!state.food[g.id]||state.energy+g.energy>100?'disabled':''}>使用（${state.food[g.id]||0}）</button></div>`).join('')}</div><p class="muted">避免溢出：超過 100 的補給無法使用。</p><button class="btn gold" data-go-shop>到商店補貨 ›</button>`);}
function orderModal(id,side){const s=E.STOCKS.find(x=>x.id===id);if(!s)return;E.settle(state);order={id,side,price:state.market.prices[id]};modal(`<div class="eyebrow">SIMULATED ORDER</div><h2>${({buy:'買進',sell:'賣出',short:'融券放空',cover:'買進回補'})[side]} ${s.name}</h2><p>${id} · 目前價格 <b>${(order.price/100).toFixed(2)}</b></p><form id="trade-form"><label class="field-label">股數（1 張 = 1,000 股）<input id="trade-qty" type="number" min="1" max="100000" step="1" value="1" required></label><div class="exchange-row"><span>交易金額</span><b id="order-total">${(order.price/100).toFixed(2)}</b></div><p class="muted">持有 ${state.holdings[id]?.qty||0} 股 · 可用 ${money(state.cash)} 新台幣</p><button class="btn gold full" type="submit">確認${({buy:'買進',sell:'賣出',short:'融券放空',cover:'買進回補'})[side]}</button></form><p class="muted">每筆成交額 10% 稅金自動納入城市；放空另需 90% 保證金。交易金額為稅前報價。回補釋放擔保後結算，強制回補可能造成負餘額。</p>`);}
function act(fn){try{fn();save();render();}catch(e){save();header();toast(e.message);}}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.page){page=d.page;render();window.scrollTo(0,0);return;}if(d.game){tavernGame=d.game;render();return;}if(d.mode){bingoMode=d.mode;bingoNumbers=[];render();return;}if(d.number){const n=+d.number,arr=tavernGame==='bingo'?bingoNumbers:lottoNumbers,max=tavernGame==='bingo'?(bingoMode==='super'?1:10):6;if(arr.includes(n))arr.splice(arr.indexOf(n),1);else if(arr.length<max)arr.push(n);else return toast(`最多選 ${max} 個號碼`);arr.sort((a,b)=>a-b);render();return;}if(d.accept){const minutes=60;act(()=>{E.accept(state,d.accept,minutes);toast('工作開始，時間到會自動結算');});return;}if(d.region){cityRegion=d.region;mapModal();return;}if(d.mapCity){selectedCity=d.mapCity;mapModal(true);return;}if(d.joinCity){act(()=>joinCity(d.joinCity));return;}if(d.buy){act(()=>{E.buy(state,d.buy,1);toast('已放入背包，點使用可恢復電量');});return;}if(d.use){const opened=$('#modal').open;act(()=>{E.use(state,d.use);toast('補給完成，電量已恢復');if(opened)staminaModal();});return;}if(d.sell){act(()=>{E.sell(state,d.sell);toast('小物已售出，款項已入帳');});return;}if(d.sellPrize){act(()=>{E.sell(state,d.sellPrize,'prize');toast('紀念品已售出');});return;}if(d.trade){orderModal(d.trade,d.side);return;}if(d.goShop!==undefined){$('#modal').close();page='shop';render();return;}if(d.spin){if(spinning)return;act(()=>{E.slots(state,Math.random,Date.now(),+d.spin);spinning=true;});if(spinning)setTimeout(()=>{spinning=false;render();},850);return;}if(d.action){switch(d.action){case'refresh-jobs':act(()=>{E.refresh(state);toast('已更新職缺，進行中的工作保留');});break;case'gold-prize':act(()=>{const p=E.ichiban(state,Math.random,true);modal(`<h2>${p.name}</h2><div class="prize-reveal">${p.icon}</div><p>收藏已入背包，另贈黃金元氣飲一瓶。</p>`);});break;case'choose':cityRegion='all';selectedCity=state.city||selectedCity;mapModal();break;case'stamina':staminaModal();break;case'next-jobs':act(()=>{E.finishNotice(state);page='jobs';});break;case'wallet':modal(`<h2>我的生活帳本</h2><p>${icon('cash')} 遊戲新台幣 ${money(state.cash)}</p>${ledger(15)}<p class="muted">不可兌現，與儲值黃金分開記錄。</p>`);break;case'gold':modal(`<h2>${icon('gold')} 黃金帳戶</h2><p>持有 ${state.premium} 黃金</p><p class="muted">儲值尚未串接。黃金可刷新職缺、購買高級補給與抽取典藏一番賞。不能直接兌換新台幣或投入酒館與股市。</p>`);break;case'quick-pick':if(tavernGame==='bingo')bingoNumbers=E.sample(80,bingoMode==='super'?1:5).sort((a,b)=>a-b);else lottoNumbers=E.sample(49,6).sort((a,b)=>a-b);render();break;case'place-ticket':act(()=>{E.bet(state,tavernGame,bingoMode,tavernGame==='bingo'?bingoNumbers:lottoNumbers,bingoStake);toast('已記錄，開獎後自動結算');});break;case'ichiban':act(()=>{const prize=E.ichiban(state);modal(`<div class="eyebrow">YOUR SOUVENIR</div><h2>${prize.name}</h2><div class="prize-reveal">${prize.icon}</div><p>已放入收藏背包，可保留或在商店以 ${prize.sell} 新台幣售出。</p><p class="muted">純遊戲紀念品，沒有實物或現金獎品。</p>`);});break;case'spin':if(spinning)return;act(()=>{E.slots(state);spinning=true;});if(spinning)setTimeout(()=>{spinning=false;if(page==='tavern')render();},850);break;}}});
document.addEventListener('change',e=>{if(e.target.id==='bingo-stake'){bingoStake=+e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='trade-qty'&&order){const qty=Number(e.target.value);$('#order-total').textContent=Number.isInteger(qty)&&qty>0?money(qty*order.price/100):'—';}});
document.addEventListener('submit',e=>{if(e.target.id!=='trade-form')return;e.preventDefault();act(()=>{E.settle(state);if(!order||state.market.prices[order.id]!==order.price)throw Error('行情已更新，請關閉後重新確認報價');const result=E.trade(state,order.id,order.side,Number($('#trade-qty').value));$('#modal').close();toast('交易完成，成交金額 '+money(result.total));});});
$('.close').onclick=()=>$('#modal').close();$('#help').onclick=()=>modal('<h2>新寶島生活指南</h2><p>在就業所同時接多份工作賺取新台幣，電量不足可購買補給。工作小物能在商店出售，也可使用遊戲資源參加酒館小遊戲、收藏一番賞紀念品與買賣虛構股票。</p><p>所有倒數依目前裝置時間；離線工作、已參加的開獎及行情會在再次開啟時結算。這是本機模擬，並非多人正式伺服器。</p><p class="muted">遊戲資源不可兌現，不連接真實彩券、金流或證券帳戶。拍賣行尚待設計。</p>');$('#profile').onclick=()=>modal(`<h2>${state.playerId}</h2><p>家鄉：${state.city||'尚未選擇'}<br>社會歷練：${money(state.exp)}<br>累積納稅金額：${money(state.tax)}</p><p class="muted">本機生活模擬 · LINE 登入尚未連接</p>`);
let lastDraws=E.period(state,'bingo').id+':'+E.period(state,'lotto').id;
function tick(){const priorDay=state.daily.day,priorJob=state.jobs.length,priorEnergy=state.energy,priorHour=state.market.hour,priorTickets=state.tickets.filter(t=>t.status==='pending').length;E.settle(state);const draws=E.period(state,'bingo').id+':'+E.period(state,'lotto').id;const changed=priorDay!==state.daily.day||(priorJob!==state.jobs.length)||priorEnergy!==state.energy||priorHour!==state.market.hour||priorTickets!==state.tickets.filter(t=>t.status==='pending').length||draws!==lastDraws;if(changed){lastDraws=draws;save();if(!$('#modal').open)render();else header();}document.querySelectorAll('[data-until]').forEach(el=>el.textContent=clock(Number(el.dataset.until)-Date.now()));const bar=document.querySelector('[data-job-progress]');if(bar&&state.job)bar.style.width=Math.min(100,(Date.now()-state.job.start)/(state.job.end-state.job.start)*100)+'%';}
E.settle(state);save();render();setInterval(tick,1000);window.addEventListener('pagehide',save);

